section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/rag-policy.json",
  "title": "RAGPolicy",
  "type": "object",
  "required": ["project_id", "header", "signals", "actions", "review_log", "colour_history"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "colour": {"enum": ["green", "amber", "red"]},
    "signal_id": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "anchor": {"type": "string", "pattern": "^(incident-[A-Za-z0-9._-]+|postmortem-[A-Za-z0-9._-]+|policy://[^\\s]+|baseline-[A-Za-z0-9._-]+)$"},
    "signal_change": {
      "type": "object",
      "required": ["signal_id", "reason"],
      "properties": {
        "signal_id": {"$ref": "#/definitions/signal_id"},
        "reason": {"type": "string", "minLength": 10},
        "evidence": {"type": "array", "items": {"$ref": "#/definitions/anchor"}}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "project_id": {"type": "string", "minLength": 2},
    "header": {
      "type": "object",
      "required": ["owner", "version", "last_reviewed", "reporting_cadence_days"],
      "additionalProperties": false,
      "properties": {
        "owner": {
          "type": "object",
          "required": ["role", "person"],
          "properties": {"role": {"type": "string", "minLength": 2}, "person": {"type": "string", "minLength": 2}}
        },
        "version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?$"},
        "last_reviewed": {"$ref": "#/definitions/date"},
        "reporting_cadence_days": {"type": "integer", "minimum": 1, "maximum": 31}
      }
    },
    "signals": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["signal_id", "unit", "input_source", "comparator", "amber_threshold", "red_threshold", "evidence"],
        "additionalProperties": false,
        "properties": {
          "signal_id": {"$ref": "#/definitions/signal_id"},
          "unit": {"enum": ["percent", "count", "ratio", "boolean"]},
          "input_source": {
            "type": "object",
            "required": ["system", "query"],
            "properties": {
              "system": {"type": "string", "minLength": 2},
              "query": {
                "type": "string",
                "minLength": 3,
                "not": {"pattern": "(?i)(estimate|gut|feel|consensus|opinion|ask the|check-in)"}
              }
            }
          },
          "comparator": {"enum": ["gt", "lt", "gte", "lte", "eq"]},
          "amber_threshold": {"type": "number"},
          "red_threshold": {"type": "number"},
          "evidence": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/definitions/anchor"}}
        },
        "allOf": [
          {"if": {"properties": {"signal_id": {"pattern": "^(schedule|budget)"}}}, "then": {"properties": {"signal_id": {"pattern": "_variance_pct$"}, "unit": {"const": "percent"}}}},
          {"if": {"properties": {"comparator": {"const": "eq"}}}, "then": {"properties": {"unit": {"const": "boolean"}}}}
        ]
      }
    },
    "actions": {
      "type": "object",
      "required": ["green", "amber", "red"],
      "additionalProperties": false,
      "properties": {
        "green": {"type": "string", "minLength": 5},
        "amber": {
          "type": "object",
          "required": ["step", "deadline_hours"],
          "properties": {
            "step": {"type": "string", "minLength": 10, "not": {"pattern": "(?i)^(discuss|monitor|keep an eye|watch)"}},
            "deadline_hours": {"type": "integer", "minimum": 1}
          }
        },
        "red": {
          "type": "object",
          "required": ["playbook", "first_step", "within_hours", "fires_at"],
          "properties": {
            "playbook": {"type": "string", "minLength": 3},
            "first_step": {"type": "string", "minLength": 10, "not": {"pattern": "(?i)^(discuss|monitor|keep an eye|watch)"}},
            "within_hours": {"type": "integer", "minimum": 1, "maximum": 72},
            "fires_at": {"const": "compute_time"}
          }
        }
      }
    },
    "review_log": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["logged_at", "kind", "person"],
        "properties": {
          "logged_at": {"$ref": "#/definitions/date"},
          "kind": {"enum": ["review", "override"]},
          "person": {"type": "string", "minLength": 2},
          "version_after": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?$"},
          "signals_removed": {"type": "array", "items": {"$ref": "#/definitions/signal_change"}},
          "signals_justified": {"type": "array", "items": {"$ref": "#/definitions/signal_change"}},
          "signals_added_or_tightened": {
            "type": "array",
            "items": {"allOf": [{"$ref": "#/definitions/signal_change"}, {"required": ["evidence"], "properties": {"evidence": {"minItems": 1}}}]}
          },
          "cycle_date": {"$ref": "#/definitions/date"},
          "computed_colour": {"$ref": "#/definitions/colour"},
          "reported_colour": {"$ref": "#/definitions/colour"},
          "reason": {"type": "string", "minLength": 10}
        },
        "allOf": [
          {"if": {"properties": {"kind": {"const": "review"}}}, "then": {"required": ["version_after", "signals_removed", "signals_justified", "signals_added_or_tightened"]}},
          {"if": {"properties": {"kind": {"const": "override"}}}, "then": {"required": ["cycle_date", "computed_colour", "reported_colour", "reason"]}},
          {"if": {"properties": {"kind": {"const": "override"}, "computed_colour": {"const": "red"}}, "required": ["computed_colour"]}, "then": {"properties": {"reported_colour": {"const": "red"}}}}
        ]
      }
    },
    "colour_history": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["computed_at", "policy_version", "policy_last_reviewed", "values", "computed_colour", "reported_colour"],
        "additionalProperties": false,
        "properties": {
          "computed_at": {"$ref": "#/definitions/date"},
          "policy_version": {"type": "string", "pattern": "^[0-9]+\\.[0-9]+(\\.[0-9]+)?$"},
          "policy_last_reviewed": {"$ref": "#/definitions/date"},
          "values": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "required": ["signal_id", "value"],
              "properties": {"signal_id": {"$ref": "#/definitions/signal_id"}, "value": {"type": "number"}}
            }
          },
          "computed_colour": {"$ref": "#/definitions/colour"},
          "reported_colour": {"$ref": "#/definitions/colour"},
          "red_escalated_at": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}"}
        },
        "if": {"properties": {"computed_colour": {"const": "red"}}},
        "then": {"required": ["red_escalated_at"], "properties": {"reported_colour": {"const": "red"}}}
      }
    }
  }
}

example.code:
{
  "project_id": "checkout",
  "header": {
    "owner": {"role": "pm", "person": "olena.k"},
    "version": "1.4.0",
    "last_reviewed": "2026-05-10",
    "reporting_cadence_days": 7
  },
  "signals": [
    {
      "signal_id": "schedule_variance_pct",
      "unit": "percent",
      "input_source": {"system": "PM", "query": "PM estimate at the weekly sync"},
      "comparator": "gt",
      "amber_threshold": "significant",
      "red_threshold": 20,
      "evidence": ["TBD"]
    },
    {
      "signal_id": "test_coverage_pct",
      "unit": "percent",
      "input_source": {"system": "SonarQube", "query": "project CHK measure coverage"},
      "comparator": "lt",
      "amber_threshold": 60,
      "red_threshold": 70,
      "evidence": ["policy://eng/coverage-floor"]
    }
  ],
  "actions": {
    "green": "continue normal cadence",
    "amber": {"step": "discuss at the next sync", "deadline_hours": 72},
    "red": {"playbook": "distressed-project-rescue", "first_step": "sponsor notified and rescue playbook opened", "within_hours": 4, "fires_at": "next_sync"}
  },
  "review_log": [
    {
      "logged_at": "2026-05-25",
      "kind": "override",
      "person": "olena.k",
      "cycle_date": "2026-05-25",
      "computed_colour": "red",
      "reported_colour": "amber",
      "reason": "steering committee is on Thursday; the team is confident the slip recovers"
    }
  ],
  "colour_history": [
    {
      "computed_at": "2026-05-25",
      "policy_version": "1.4.0",
      "policy_last_reviewed": "2026-05-10",
      "values": [
        {"signal_id": "schedule_variance_pct", "value": 22},
        {"signal_id": "test_coverage_pct", "value": 80}
      ],
      "computed_colour": "amber",
      "reported_colour": "amber"
    }
  ]
}
